<template><section><b>Run {{r.runId}}</b><span v-if="r.traceId"> Trace {{r.traceId}}</span><div class="span" v-for="s in r.spans" :key="s.id"><b>{{s.status==='success'?'OK':'FAIL'}}</b> {{s.node_type}} / {{s.node_id}} ({{s.duration?.toFixed(3)}}s)<details><summary>Input / Output</summary><pre>{{JSON.stringify({input:s.input,output:s.output,error:s.error},null,2)}}</pre></details></div><div v-for="e in r.events" :key="e.timestamp">{{e.event}} {{e.node_id||''}} {{e.data?.content||''}}</div></section></template><script setup lang="ts">import{useRuntimeStore}from '../../stores/runtime';const r=useRuntimeStore()</script><style scoped>section{height:180px;overflow:auto;padding:10px;border-top:1px solid #ddd;font:12px monospace}.span{padding:4px 0;border-bottom:1px solid #eee}pre{white-space:pre-wrap}</style>
